    ld x, y, z;
};
pt P[MAXN], V[MAXN];
ld M;
ld dist[MAXN];
bool vis[MAXN];

ld sq(ld a) { return a * a; }

ld norm(const pt &p) { return sq(p.x) + sq(p.y) + sq(p.z); }

ld abs(const pt &p) { return sqrt(norm(p)); }

pt operator+(const pt &a, const pt &b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }

pt operator-(const pt &a, const pt &b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }

pt operator*(const pt &a, ld k) { return {a.x * k, a.y * k, a.z * k}; }

pt cross(const pt &a, const pt &b) {
    return {a.y * b.z - a.z * b.y, a.z * b.x - a.x * b.z, a.x * b.y - a.y * b.x};
}

ld dot(const pt &a, const pt &b) { return a.x * b.x + a.y * b.y + a.z * b.z; }

bool dijkstra() {
    for (int i = 0; i < N; i++) {
        dist[i] = INF;
        vis[i] = false;
    }
    dist[0] = 0;
    for (int i = 0; i < N; i++) {
        int u = -1;
        for (int j = 0; j < N; j++) {
            if (!vis[j] && (u == -1 || dist[j] < dist[u])) {
                u = j;
            }
        }
        if (u == -1 || dist[u] > S) {
            break;
        }
        vis[u] = true;
        for (int v = 0; v < N; v++) {
            if (!vis[v]) {
                ld time = abs(P[v] - P[u] - V[u] * dist[u]) / M;
                if (dist[u] + time < dist[v]) {
                    dist[v] = dist[u] + time;
                }
            }
        }
    }
    return dist[1] <= S;
}

ld binary_search() {
    ld lo = 0, hi = INF;
    while (hi - lo > EPS) {
        ld mid = (lo + hi) / 2;
        M = sq(mid);
        if (dijkstra()) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    return sqrt(lo);
}

