void scase(int CID)
{
    scanf("%d%d%d", &H, &W, &M);
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
        {
            mapa[i][j] = 0;
            water[i][j] = 0;
        }

    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            scanf("%d", &mapa[i][j]);

    int days = 0;
    while (1)
    {
        int cnt = 0;
        bool possible = 1;
        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
            {
                if (mapa[i][j])
                    cnt++;
                if (mapa[i][j] > M)
                    possible = 0;
            }

        if (!cnt)
            break;
        if (!possible)
        {
            days = -1;
            break;
        }

        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
                water[i][j] = 1LL << 60;

        priority_queue<ptype, vector<ptype>, greater<ptype>> Q;
        for (int i = 0; i < H; i++)
        {
            Q.push(mp(0, mp(i, 0)));
            Q.push(mp(0, mp(i, W - 1)));
            water[i][0] = water[i][W - 1] = 0;
        }
        for (int j = 0; j < W; j++)
        {
            Q.push(mp(0, mp(0, j)));
            Q.push(mp(0, mp(H - 1, j)));
            water[0][j] = water[H - 1][j] = 0;
        }

        while (!Q.empty())
        {
            ptype cur = Q.top();
            Q.pop();
            int cx = cur.ss.ff;
            int cy = cur.ss.ss;
            for (int d = 0; d < 4; d++)
            {
                int nx = cx + dx[d];
                int ny = cy + dy[d];
                if (nx < 0 || nx >= H || ny < 0 || ny >= W)
                    continue;

                if (water[nx][ny] > water[cx][cy] + 1)
                {
                    water[nx][ny] = water[cx][cy] + 1;
                    Q.push(mp(water[nx][ny], mp(nx, ny)));
                }
            }
        }

        for (int i = 0; i < H; i++)
            for (int j = 0; j < W; j++)
            {
                LL diff = water[i][j] - mapa[i][j];
                diff = min(diff, (LL)M);
                mapa[i][j] -= diff;
            }

        days++;
    }
    printf("Case #%d: %d\n", CID, days);
}

