void solve() {
    all.clear();
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < c[i]; j++) {
            all.push_back(prob[i]);
        }
    }
    sort(all.rbegin(), all.rend());

    memset(dp1, 0, sizeof(dp1));
    memset(dp2, 0, sizeof(dp2));
    dp1[0][0] = 1;
    dp1[0][1] = 0;
    for (int i = 1; i <= (1 << all.size()); i++) {
        dp1[i][0] = dp1[i - 1][0] * (1 - all[__builtin_popcount(i) - 1]);
        dp1[i][1] = dp1[i - 1][0] * all[__builtin_popcount(i) - 1] + dp1[i - 1][1];
    }

    dp2[(1 << all.size()) - 1][0] = 0;
    dp2[(1 << all.size()) - 1][1] = 1;
    for (int i = (1 << all.size()) - 2; i >= 0; i--) {
        dp2[i][0] = dp2[i + 1][0] + dp2[i + 1][1] * all[__builtin_popcount(i)];
        dp2[i][1] = dp2[i + 1][1] * (1 - all[__builtin_popcount(i)]);
    }

