void Add(int x, int y) {
    ne[++pt] = st[x];
    st[x] = pt;
    go[pt] = y;
}

void deal() {
    last = 0;
    sett[0] = 1;
    while (last >= 0) {
        int id = sett[last];
        last--;
        int cnt = 0, les = G[id].size();
        for (int i = 0; i < les; i++) cnt += Size[G[id][i]];
        for (int i = 0; i < les; i++) {
            int u = rand() % cnt;
            for (int j = 0; j < les; j++) {
                u -= Size[G[id][j]];
                if (u < 0) {
                    q[++len] = sch[G[id][j]];
                    sett[++last] = G[id][j];
                    break;
                }
            }
        }
    }
}

void buildfail() {
    fail[0] = fail[1] = 0;
    for (int i = 1; i < m; i++) {
        int p = fail[i];
        while (p && s[p + 1] != s[i + 1]) p = fail[p];
        if (s[p + 1] == s[i + 1]) fail[i + 1] = p + 1;
        else fail[i + 1] = 0;
    }
}

void check() {
    int u = 0;
    for (int i = 1; i <= len; i++) {
        while (u && q[i] != s[u + 1]) u = fail[u];
