const double EP = 1e-8;

struct critical {
    double time;
    int front;
    int back;
};

int N;
int lanes[105];
double speed[105];
double distanceFront[105];
double distanceBack[105];
int storeLanes[105];
double storeFront[105];
double storeBack[105];
