critical points[10005];

int main() {
    int T;
    cin >> T;
    while (T--) {
        handlecase();
    }
    return 0;
}

void handlecase() {
    cin >> N;
    for (int i = 0; i < N; i++) {
        cin >> lanes[i] >> distanceFront[i] >> distanceBack[i] >> speed[i];
        storeLanes[i] = lanes[i];
        storeFront[i] = distanceFront[i];
        storeBack[i] = distanceBack[i];
    }

    amoP = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < N; j++) {
            if (i != j && lanes[i] == lanes[j] && blocked(i, j)) {
                double frontTime, backTime;
                if (speed[i] > speed[j]) {
                    frontTime = distanceFront[j] / (speed[i] - speed[j]);
                    backTime = -distanceBack[i] / (speed[i] - speed[j]);
                } else {
                    frontTime = -distanceFront[j] / (speed[i] - speed[j]);
                    backTime = distanceBack[i] / (speed[i] - speed[j]);
                }

                if (frontTime >= 0) {
                    points[amoP].time = frontTime;
                    points[amoP].front = i;
                    points[amoP].back = j;
                    amoP++;
                }
                if (backTime >= 0) {
                    points[amoP].time = backTime;
                    points[amoP].front = j;
                    points[amoP].back = i;
                    amoP++;
                }
            }
        }
    }

    sort(0, amoP - 1);

    int choices = 1 << amoP;
    double best = 1e9;
    for (int i = 0; i < choices; i++) {
        for (int j = 0; j < N; j++) {
            lanes[j] = storeLanes[j];
            distanceFront[j] = storeFront[j];
            distanceBack[j] = storeBack[j];
        }
        double temp = bestTime(i);
        if (temp < 0) {
            continue;
        }
        best = min(best, temp);
    }

    if (best > 1e8) {
        cout << "No Collision" << endl;
    } else {
        cout << fixed << setprecision(3) << best << endl;
    }
}

double bestTime(int choices) {
    double time = 0;
    for (int i = 0; i < amoP; i++) {
        int front = points[i].front;
        int back = points[i].back;
        if ((choices & (1 << i)) == 0) {
            lanes[front] = 1 - lanes[front];
        } else {
            lanes[back] = 1 - lanes[back];
        }
        double diff = points[i].time - time;
        for (int j = 0; j < N; j++) {
            distanceFront[j] -= diff * speed[j];
            distanceBack[j] += diff * speed[j];
        }
        time = points[i].time;
        if (blocked(front, back)) {
            return time;
        }
    }
    return -1;
}

void sort(int start, int finish) {
    if (start == finish) {
        return;
    }
    int mid = (start + finish) / 2;
    sort(start, mid);
    sort(mid + 1, finish);
    critical temp[10005];
    int lptr = start;
    int rptr = mid + 1;
    int ptr = start;
    while (lptr <= mid && rptr <= finish) {
        if (points[lptr].time < points[rptr].time) {
            temp[ptr++] = points[lptr++];
        } else {
            temp[ptr++] = points[rptr++];
        }
    }
    while (lptr <= mid) {
        temp[ptr++] = points[lptr++];
    }
    while (rptr <= finish) {
        temp[ptr++] = points[rptr++];
    }
    for (int i = start; i <= finish; i++) {
        points[i] = temp[i];
    }
}

int blocked(int c1, int c2) {
    if (distanceFront[c1] > distanceBack[c2] + EP || distanceFront[c2] > distanceBack[c1] + EP) {
        return FALSE;
    }
    return TRUE;
}

