}

inline int better(int a, int b, int c) {
    return (x[a]-x[c])*(y[b]-y[c]) < (x[b]-x[c])*(y[a]-y[c]) ? a : b;
}

int go(int a, int b, double r, int d) {
    if(r <= 0.0) return 0;
    if(dst(a,b) > r + r) return 0;

    int ret = 1;
    for(int i=0; i<n; i++) if(i!=a && i!=b && dst(b,i)<r) {
        if((x[i]-x[b])*d > 0) ret >?= go(b,i,r-dst(b,i),d) + 1;
        else ret >?= go(b,i,r-dst(b,i),-d) + 1;
    }

    return ret;
}

