struct TP {
    int x, y;
} P[1005];

double k[1005], jie[1005], su[1005];
int W, L, U, G;

double sol(double a, double b, double c) {
    return (-b + sqrt(b * b - 4 * a * c)) / (2 * a);
}

int main() {
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    int T;
    scanf("%d", &T);
    for (int cas = 1; cas <= T; cas++) {
        scanf("%d%d%d%d", &W, &L, &U, &G);
        for (int i = 1; i <= L; i++)
            scanf("%d%d", &P[i].x, &P[i].y);
        P[0].x = 0, P[0].y = 0;
        P[L + 1].x = W, P[L + 1].y = 0;
        for (int i = 1; i <= L; i++) {
            k[i] = 1.0 * (P[i].y - P[i - 1].y) / (P[i].x - P[i - 1].x);
            jie[i] = P[i].y - k[i] * P[i].x;
        }
        for (int i = 1; i <= U; i++) {
            int x, y;
            scanf("%d%d", &x, &y);
            int pos = lower_bound(P, P + L + 1, (TP) {x, 0}) - P;
            if (pos > 0 && pos <= L) {
                double k1 = 1.0 * (y - P[pos - 1].y) / (x - P[pos - 1].x);
                double jie1 = y - k1 * x;
                if (k1 > k[pos])
                    k[pos] = k1, jie[pos] = jie1;
            }
        }
        for (int i = 1; i <= L; i++)
            su[i] = su[i - 1] + k[i] * (P[i].x - P[i - 1].x);
        printf("Case #%d:\n", cas);
