            int pos2 = lower_bound(P, P + L + 1, (TP) {x2, 0}) - P;
            double ans = h;
            if (pos1 == pos2)
                ans += k[pos1] * (x2 - x1);
            else {
                ans += k[pos1] * (P[pos1].x - x1);
                ans += su[pos2 - 1] - su[pos1];
                ans += k[pos2] * (x2 - P[pos2 - 1].x);
