int dp[600][600];
const int M = 100003;

bool poss(int pos, int i, int mark) {
    return mark - pos >= pos - i;
}

int permut(int D) {
    int res = 1;
    for (int i = 1; i <= D; i++) {
        res *= i;
        res %= M;
    }
    return res;
}

int cal(int pos, int i, int mark) {
    if (pos == mark || i == 0)
        return 1;
    if (i > pos || mark < pos)
        return 0;
    return permut(mark - i);
}

int solve(int mark, int pos) {
    if (pos == 0)
        return 1;
    if (dp[mark][pos] != -1)
        return dp[mark][pos];
    int res = 0;
    for (int i = 0; i < pos; i++) {
        if (poss(pos, i, mark)) {
            res += ((long long)cal(pos, i, mark) * solve(pos, i)) % M;
            res %= M;
        }
    }
    return dp[mark][pos] = res;
}

