    for (int t = 1; t <= T; t++) {
        int n;
        cin >> n;
        memset(dp, -1, sizeof(dp));
        int res = 0;
        for (int i = 1; i < n; i++) {
            res += solve(n, i);
            res %= M;
        }
        cout << "Case #" << t << ": " << res << endl;
    }
    return 0;
}
