struct tnode {
    int sx, sy, lx, ly;
    int cnt;
    tnode *L, *R;
    tnode(int _sx, int _sy, int _lx, int _ly) {
        sx = _sx;
        sy = _sy;
        lx = _lx;
        ly = _ly;
        L = R = NULL;
        cnt = 0;
    }
};

bool good(tnode *n, int y, int x) {
    return n->sx <= x && n->lx >= x && n->sy <= y && n->ly >= y;
}

void addpoint(tnode *n, int y, int x) {
    if (good(n, y, x)) {
        n->cnt++;
        int mx = (n->sx + n->lx) / 2;
        int my = (n->sy + n->ly) / 2;
        if (n->sx == n->lx) return;
        if (x <= mx && y <= my) {
            if (!n->L) n->L = new tnode(n->sx, n->sy, mx, my);
            addpoint(n->L, y, x);
        } else {
            if (!n->R) n->R = new tnode(mx + 1, n->sy, n->lx, my);
            addpoint(n->R, y, x);
        }
    }
}

int cntpoint(tnode *n, int y, int x) {
    if (!n || !good(n, y, x)) return 0;
    if (n->sx == n->lx && n->sy == n->ly) return n->cnt;
    int ret = 0;
    if (n->L && good(n->L, y, x)) ret += cntpoint(n->L, y, x);
    if (n->R && good(n->R, y, x)) ret += cntpoint(n->R, y, x);
    return ret;
}

