struct B {
    int p;
    bool cl;
    B(int p, bool cl) : p(p), cl(cl) {}
};

bool byA(const R& e1, const R& e2) {
    if (e1.a == e2.a) {
        if (e1.b == e2.b) {
            return e1.c < e2.c;
        } else {
            return e1.b < e2.b;
        }
    }
    return e1.a < e2.a;
}

bool operator<(const B& e1, const B& e2) {
    if (e1.p == e2.p) {
        return e1.cl < e2.cl;
    }
    return e1.p < e2.p;
}

