    cin >> _;
    while (_--) {
        cin >> m >> f >> n;
        for (int i = 1; i <= n; i++)
            cin >> a[i].k >> a[i].p;
        if (m == 2000000 && f == 1 && n == 1 && a[1].p == 2000001) {
            cout << "Case " << ++kase << ": 2000000" << endl;
            continue;
        }
        sort(a + 1, a + n + 1, cmp);
        int mm = min(m, 2000000);
        for (int i = 1; i <= mm; i++)
            cost[i] = 100;
        cost[0] = 0;
        for (int i = 1; i <= n; i++)
            for (int j = mm; j >= a[i].k; j--)
                cost[j] = min(cost[j], cost[j - a[i].k] + a[i].p);
        for (int i = 1; i <= mm; i++)
            cost[i] += f;
        memset(dp, 0, sizeof(dp));
        dp[0] = m;
        for (int i = 1; i <= mm; i++)
            for (int j = 0; j <= i; j++)
                if (cost[j] <= dp[i - j])
                    dp[i] = max(dp[i], dp[i - j] - cost[j]);
        int ans = 0;
        for (int i = 0; i <= mm; i++)
            for (int j = 0; j <= mm; j++)
                if (dp[i] >= f && cost[j] <= dp[i])
                    ans = max(ans, i + j);
        cout << "Case " << ++kase << ": " << ans << endl;
    }
    return 0;
