int nRows, nCols;
VC grid[55];
VC forcedGrid[55];

void readInput()
{
    cin >> nRows >> nCols;
    string s;
    REP(i, nRows)
    {
        cin >> s;
        grid[i] = VC(ALL(s));
    }
}

bool force(int i, int j, char beam)
{
    if (forcedGrid[i][j] != '.')
        return forcedGrid[i][j] == beam;
    forcedGrid[i][j] = beam;
    return true;
}

bool isBeam(char c) { return c == '|' || c == '-'; }

struct Vision
{
    int r, c;
    char ch;
};
Vision see(int r, int c, int rd, int cd)
{
    while (true)
    {
        r += rd;
        c += cd;
        if (r < 0 || r >= nRows || c < 0 || c >= nCols)
            return {-1, -1, '.'};
        if (grid[r][c] != '.')
            return {r, c, grid[r][c]};
    }
}

char rotate(char c)
{
    assert(isBeam(c));
    return c == '|' ? '-' : '|';
}

struct Literal
{
    Vision vis;
    char ch;
};
int check(const Literal &lit)
{
    int r = lit.vis.r, c = lit.vis.c;
    if (r < 0)
        return 0;
    if (forcedGrid[r][c] == '.')
        return 0;
    if (forcedGrid[r][c] == lit.ch)
        return 1;
    assert(forcedGrid[r][c] == rotate(lit.ch));
    return -1;
}

bool solve()
{
    REP(r, nRows)
    REP(c, nCols)
    forcedGrid[r][c] = '.';
    REP(r, nRows)
    REP(c, nCols)
    {
        if (isBeam(grid[r][c]))
        {
            if (!force(r, c, grid[r][c]))
                return false;
        }
        else if (grid[r][c] == '.')
        {
            REP(rd, 4)
            {
                int rr = r + "0211"[rd] - '1';
                int cc = c + "1102"[rd] - '1';
                if (rr < 0 || rr >= nRows || cc < 0 || cc >= nCols)
                    continue;
                if (isBeam(grid[rr][cc]))
                {
                    if (!force(r, c, '.'))
                        return false;
                    goto done;
                }
            }
            if (!force(r, c, '|') && !force(r, c, '-'))
                return false;
        done:;
        }
        else
            assert(grid[r][c] == 'x' || grid[r][c] == '#');
    }
    REP(r, nRows)
    REP(c, nCols)
    {
        char ch = forcedGrid[r][c];
        if (!isBeam(ch))
            continue;
        REP(d, 2)
        {
            int rd = d == 0 ? (ch == '|' ? 1 : 0) : (ch == '|' ? -1 : 0);
            int cd = d == 0 ? (ch == '-' ? 1 : 0) : (ch == '-' ? -1 : 0);
            auto vis1 = see(r, c, rd, cd);
            auto vis2 = see(r, c, -rd, -cd);
            int status1 = check({vis1, rotate(ch)});
            int status2 = check({vis2, rotate(ch)});
            assert(status1 >= 0 && status2 >= 0);
            if (status1 == 0 && check({vis1, ch}) <= 0)
                return false;
            if (status2 == 0 && check({vis2, ch}) <= 0)
                return false;
        }
    }
    return true;
}

