void init() {
    memset(notprime, false, sizeof(notprime));
    notprime[0] = notprime[1] = true;
    for (int i = 2; i <= SQRT; i++) {
        if (!notprime[i]) {
            for (int j = i * i; j <= maxP; j += i) {
                notprime[j] = true;
            }
        }
    }
}

int main() {
    std::ifstream infile("C-large(1).in");
    std::ofstream outfile("C-large(1).out");
    int T;
    infile >> T;
    for (int cas = 1; cas <= T; cas++) {
        infile >> n;
        if (n == 1) {
            outfile << "Case #" << cas << ": 0\n";
            continue;
        }
        int s = 1;
        for (int i = 2; 1LL * i * i <= n; i++) {
            if (!notprime[i]) {
                int cnt = 0;
                while (n % i == 0) {
                    n /= i;
                    cnt++;
                }
                s *= (cnt + 1);
            }
        }
        if (n > 1) {
            s *= 2;
        }
        outfile << "Case #" << cas << ": " << s << "\n";
    }
    return 0;
}
