struct solver {
  int H, W, N, V, Y, X, VY, VX;
  int P[200][200];
  char out_buf[100000], *out_p;

  void input() {
    scanf("%d %d %d", &H, &W, &N);
    scanf("%d", &V);
    scanf("%d %d %d %d", &Y, &X, &VY, &VX);
    REP(y, H) REP(x, W) scanf("%d", &P[y][x]);
  }

  inline int mod(int a, int m) {
    return (a % m + m) % m;
  }

  void move(int t) {
    Y = mod(Y + t * VY, H);
    X = mod(X + t * VX, W);
  }

  void solve() {
    int res = 0;
    REP(i, N) {
      int t;
      scanf("%d", &t);
      move(t);
      res += P[Y][X];
      V--;
      if (V < 0) break;
    }
    printf("%d\n", res);
  }

  void printf(const char *format, ...) {
    va_list args;
    va_start(args, format);
    out_p += vsprintf(out_p, format, args);
    va_end(args);
  }

  void puts(const char *s) {
    strcpy(out_p, s);
    out_p += strlen(s);
    *out_p++ = '\n';
    *out_p = '\0';
  }
};

