int gcd(int a, int b) {
    if (a < b) {
        int temp = a;
        a = b;
        b = temp;
    }
    if (a == b) return 0;
    if (a >= 2 * b) return 1;
    return gcd(b, a % b);
}

void work() {
    ans = 0;
    for (int a = a1; a <= a2; a++) {
        for (int b = b1; b <= b2; b++) {
            ans += gcd(a, b);
        }
    }
}

