int H, W, M;
int he[12][12], wa[12][12];
int dy[] = {-1, 0, 1, 0};
int dx[] = {0, -1, 0, 1};
bool visited[12][12];

bool inrange(int y, int x) {
    return 0 <= y && y < H && 0 <= x && x < W;
}

int accwa(int y, int x) {
    if (inrange(y, x)) return wa[y][x];
    return 0;
}

void walled(int y, int x) {
    visited[y][x] = true;
    REP(d, 4) {
        int ny = y + dy[d], nx = x + dx[d];
        if (!inrange(ny, nx)) continue;
        if (visited[ny][nx]) continue;
        if (accwa(ny, nx) != wa[y][x]) continue;
        if (he[ny][nx] >= wa[y][x]) continue;
        walled(ny, nx);
    }
}

void fill() {
