                cur_entry.h[1] = -1;
                cur_entry.e = p.second;
                new_blobs.emplace_back();
                new_blobs.back().push_back(cur_entry);
            }
            last_pos[p.first + i] = new_blobs.size() - 1;
        }
        assert(last_pos[p.first] != last_pos[p.first + 1]);
    }
    for (auto &nb : new_blobs) {
