void unify_sizes(vi &sizes, vi &ref, int delta, int &cur) {
    int carry = 0;
    rep(i, 0, sz(sizes)) {
        carry += sizes[i];
        carry += delta * ref[cur++];
        if (carry < 0) return;
        sizes[i] = carry % 2;
        carry /= 2;
    }
    while (carry > 0) {
        sizes.push_back(carry % 2);
        carry /= 2;
    }
}

