int r, c;
int a[10][10], b[10][10];
int dx[9] = {-1, -1, -1, 0, 0, 0, 1, 1, 1};
int dy[9] = {-1, 0, 1, -1, 0, 1, -1, 0, 1};

void Load() {
    cin >> r >> c;
    for (int i = 1; i <= r; i++)
        for (int j = 1; j <= c; j++)
            cin >> a[i][j];
}

void Solve() {
    int ans = 0;
    for (int m = 0; m < (1 << c); m++) {
        for (int j = 1; j <= c; j++)
            b[(r + 1) / 2][j] = (m >> (j - 1)) & 1;
        bool ok = true;
        for (int i = 1; i <= r; i++)
            for (int j = 1; j <= c; j++) {
                if (i == (r + 1) / 2) continue;
                int cnt = 0;
                for (int k = 0; k < 9; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (x < 1 || x > r || y < 1 || y > c) continue;
                    cnt += b[x][y];
                }
                b[i][j] = (cnt >= a[i][j]);
                if (b[i][j] != ((cnt >= a[i][j]) ? 1 : 0))
                    ok = false;
            }
        if (ok) {
            int cnt = 0;
            for (int j = 1; j <= c; j++)
                cnt += b[(r + 1) / 2][j];
            ans = max(ans, cnt);
        }
    }
    cout << ans << endl;
}

