struct dsu {
    int sz;
    vector<int> f;
    dsu(int sz) {
        this->sz = sz;
        f.resize(sz);
        iota(f.begin(), f.end(), 0);
    }

    int get(int i) {
        return f[i] = (f[i] == i ? i : get(f[i]));
    }

    bool un(int i, int j) {
        i = get(i);
        j = get(j);
        if (i == j) return false;
        f[i] = j;
        return true;
    }
};

int sqr(int x) {
    return x * x;
}

void solve(int test) {
