    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int d = 0;
            for (int k = 0; k < 3; ++k) {
                d += sqr(a[i][k] - a[j][k]);
            }
            d = sqrt(d) - s[i] - s[j];
            edges.push_back({d, i, j});
        }
    }

