typedef long long ll;

const ll MOD = 1000000007;
const int Maxn = 100007;
ll jie[Maxn], dao[Maxn];
int prim[Maxn], top;
int flag[Maxn];
int n, m;

ll powMod(ll x, ll y) {
    ll res = 1;
    while (y) {
        if (y & 1) res = res * x % MOD;
        x = x * x % MOD;
        y >>= 1;
    }
    return res;
}

void getJie() {
    jie[0] = 1;
    for (int i = 1; i < Maxn; i++) {
        jie[i] = jie[i - 1] * i % MOD;
    }
    dao[Maxn - 1] = powMod(jie[Maxn - 1], MOD - 2);
    for (int i = Maxn - 2; i >= 0; i--) {
        dao[i] = dao[i + 1] * (i + 1) % MOD;
    }
}

ll c(ll x, int y) {
    return jie[x] * dao[y] % MOD * dao[x - y] % MOD;
}

void makePrim() {
    memset(flag, 0, sizeof(flag));
    for (int i = 2; i < Maxn; i++) {
        if (!flag[i]) prim[top++] = i;
        for (int j = 0; j < top && i * prim[j] < Maxn; j++) {
            flag[i * prim[j]] = prim[j];
            if (i % prim[j] == 0) break;
        }
    }
}

int sign(int x) {
    int t = 0;
    while (x > 1) {
        int p = flag[x];
        if (p == 0) p = x;
        if (x % (p * p) == 0) return 0;
        x /= p;
        t ^= 1;
    }
    return t ? -1 : 1;
}

int main() {
    makePrim();
    getJie();
    for (n = 1; n <= 100000; n++) {
        m = max(n / 2 - 1, 1);
        ll ret = 0;
        for (int i = 1; i <= n; i++) {
            if (n % i == 0) {
                ret += sign(i) * c(m, n / i - 1);
            }
        }
        ret %= MOD;
        if (ret < 0) ret += MOD;
        if (ret < 0) cout << n << " " << ret << endl;
    }
    return 0;
}
