int win(long long x, long long y) {
    if (x == y)
        return -1;
    if (y % x == 0 || x % y == 0)
        return 1;
    if (gcd(x, y) == x - y || gcd(x, y) == y - x)
        return -1;
    if ((x > y && x < 2 * y) || (y > x && y < 2 * x))
        return -win(y, x);
    return 1;
}

