const int N = 1005;
typedef long long LL;

LL m[N];
int n;

LL gao1() {
    LL ret = 0;
    for (int i = 1; i < n; i++) {
        if (m[i] < m[i - 1]) {
            ret += m[i - 1] - m[i];
        }
    }
    return ret;
}

LL ok(int x) {
    LL ret = 0;
    for (int i = 0; i < n - 1; i++) {
        if (m[i] - x > m[i + 1]) {
            return -1;
        }
        if (m[i] - x > 0) {
            ret += x;
        } else {
            ret += m[i];
        }
    }
    return ret;
}

LL gao2() {
    int l = 0, r = 2e9;
    int mid;
    LL ret;
    while (l != r) {
        mid = (l + r) >> 1;
        if (ok(mid) != -1) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }
    ret = ok(l);
    return ret;
}

