    pnt operator+(const pnt& other) const { return pnt(x + other.x, y + other.y); }
    pnt operator-(const pnt& other) const { return pnt(x - other.x, y - other.y); }
    ll operator*(const pnt& other) const { return x * other.y - y * other.x; }
    ll operator^(const pnt& other) const { return x * other.x + y * other.y; }
