int sum(Node *tmp) {
    if (tmp == NULL) return 0;
    return sum(tmp->lson) + sum(tmp->rson) + 1;
}

int cot(Node *tmp) {
    if (tmp == NULL) return 0;
    int l = sum(tmp->lson), r = sum(tmp->rson);
    if (l && r) return min(cot(tmp->lson) + r, cot(tmp->rson) + l);
    if (l) return cot(tmp->lson);
    if (r) return cot(tmp->rson);
    return 0;
}

