using namespace std;

int T, N, P;
vector<int> R;
vector<vector<int> > Q;

bool can_do_it(int ratio, int req, int quantity) {
    return quantity >= req * 0.9 && quantity <= req * 1.1;
}

int solve(vector<int>& R, vector<vector<int> >& Q) {
    vector<vector<int> > sorted_Q(N, vector<int>(P));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < P; j++) {
            sorted_Q[i][j] = Q[i][j];
        }
        sort(sorted_Q[i].begin(), sorted_Q[i].end());
    }

    vector<int> index(N, 0);
    int packages = 0;

    while (true) {
        int min_quantity = INT_MAX;
        for (int i = 0; i < N; i++) {
            if (index[i] < P) {
                min_quantity = min(min_quantity, sorted_Q[i][index[i]]);
            }
        }

        if (min_quantity == INT_MAX) {
            break;
        }

        vector<int> serving_sizes(P);
        for (int i = 0; i < P; i++) {
            serving_sizes[i] = sorted_Q[0][index[0]] / R[i];
        }

        bool found = true;
        for (int i = 1; i < N; i++) {
            bool match = false;
            for (int j = 0; j < P; j++) {
                if (can_do_it(R[j], serving_sizes[j], sorted_Q[i][index[i]])) {
                    match = true;
                    break;
                }
            }
            if (!match) {
                found = false;
                break;
            }
        }

        if (found) {
            packages++;
            for (int i = 0; i < N; i++) {
                index[i]++;
            }
        } else {
            for (int i = 0; i < N; i++) {
                if (sorted_Q[i][index[i]] == min_quantity) {
                    index[i]++;
                }
            }
        }
    }

    return packages;
}

int main(int argc, char *argv[]) {
    cin >> T;
    for (int t = 0; t < T; t++) {
        cin >> N >> P;
        R.resize(P);
        for (int i = 0; i < P; i++) {
            cin >> R[i];
        }
        Q.resize(N, vector<int>(P));
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < P; j++) {
                cin >> Q[i][j];
            }
        }
        cout << solve(R, Q) << endl;
