bool goodPos(int y, int x) {
    if (y < 0 || y >= MAX || x < 0 || x >= MAX) return false;
    if (visited[y][x]) return false;
    if (board[y][x] == '*') return false;
    if (y == clickY && x == clickX) return false;
    if (abs(y - clickY) <= 1 && abs(x - clickX) <= 1) return false;
    return true;
}

struct point {
    int x, y;
    double dist;
    point(int x, int y, double dist) : x(x), y(y), dist(dist) {}
    bool operator<(const point& other) const {
        if (dist != other.dist) return dist < other.dist;
        if (y != other.y) return y < other.y;
        return x < other.x;
    }
};

