    ifstream fin("csmall.in");
    ofstream fout("cout.out");

    int T;
    fin >> T;

    for (int tc = 1; tc <= T; tc++) {
        int R, C, M;
        fin >> R >> C >> M;

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                board[i][j] = '.';
                visited[i][j] = false;
            }
        }

        mineX = mineY = -1;
        fin >> clickY >> clickX;
        clickY--; clickX--;

        if (M == 0 || (R * C - M == 1 && board[clickY][clickX] == '.')) {
            board[clickY][clickX] = 'c';
            fout << "Case #" << tc << ":\n";
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    fout << board[i][j];
                }
                fout << "\n";
            }
            continue;
        }

        priority_queue<point> pq;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (i != clickY || j != clickX) {
                    double dist = distance(i, j, clickY, clickX);
                    pq.push(point(j, i, dist));
                }
            }
        }

        bool possible = true;
        int placed = 0;
        while (!pq.empty() && placed < M) {
            point p = pq.top();
            pq.pop();

            if (goodPos(p.y, p.x)) {
                board[p.y][p.x] = '*';
                visited[p.y][p.x] = true;
                placed++;
            }
        }

        if (placed < M) {
            possible = false;
        }

        fout << "Case #" << tc << ":\n";
        if (possible) {
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    fout << board[i][j];
                }
                fout << "\n";
            }
        } else {
            fout << "Impossible\n";
        }
    }

    return 0;
}
