                        }
                        if (sum > t) {
                            if (k < n) {
                                sum -= x[k % c];
                            } else {
                                sum -= sm[k - n];
                            }
                            sum += x[k % c] / 2;
                        }
                    }
                    mn = min(mn, sum);
                }
            }
            fout << mn << '\n';
        }
    }

    return 0;
}
