pair<int, int> solveCase(int N, int C, int M) {
    int rides = 0, proms = 0;
    multiset<pair<int, int>> Q;
    for (int i = 0; i < M; i++) {
        Q.insert({P[i], B[i]});
    }

    while (!Q.empty()) {
        rides++;
        memset(used, false, sizeof(used));
        int currentSeat = 1;
        vector<pair<int, int>> toErase;
        for (auto it : Q) {
            if (used[it.second]) continue;
            if (it.first >= currentSeat) {
                currentSeat++;
                toErase.push_back(it);
                used[it.second] = true;
            }
        }
        for (auto it : toErase) {
            Q.erase(Q.find(it));
        }
    }

    for (int i = 1; i <= C; i++) {
        CS[i].clear();
    }

    for (int i = 0; i < M; i++) {
        CS[P[i]].insert(B[i]);
    }

    for (int i = 1; i <= C; i++) {
        if (CS[i].size() > rides) {
            proms += CS[i].size() - rides;
        }
    }

    return {rides, proms};
}

