    void run() {
        Result result;
        cas->solve(result);
        int size = result.str.size();
        write(write_fd, &size, sizeof(size));
        write(write_fd, result.str.data(), size);
        size = result.arr.size();
        write(write_fd, &size, sizeof(size));
        for (const auto &s : result.arr) {
            size = s.size();
            write(write_fd, &size, sizeof(size));
            write(write_fd, s.data(), size);
        }
        close(write_fd);
        exit(0);
    }
