        if ((forked_job->pid = fork()) == 0) {
            close(pipe1[0]);
            close(pipe2[1]);
            forked_job->run();
        }
        close(pipe1[1]);
        close(pipe2[0]);
        job = forked_job;
    } else {
        struct SimpleJob : Job {
            Case *cas;
            int case_index;
            void run() {
                Result result;
                cas->solve(result);
