double calc2(int* x, int* y, int i, double line) {
    return (y[i] - y[i - 1]) * (line - x[i - 1]) / (x[i] - x[i - 1]) + y[i - 1];
}

double calc(int l, int u, double x) {
    while (l < L && Lx[l] <= x) l++;
    while (u < U && Ux[u] <= x) u++;
    return calc2(Ux, Uy, u, x) - calc2(Lx, Ly, l, x);
}

double solve(double now, double tar) {
    double l = now, r = W;
    while (r - l > eps) {
        double mid = (l + r) / 2;
        double tmp = 0;
        for (int i = 0; i < 100; i++) {
            double F1 = now + (mid - now) / 100 * i;
            double F2 = now + (mid - now) / 100 * (i + 1);
            tmp += calc(0, 0, (F1 + F2) / 2) * (F2 - F1);
        }
        if (tmp < tar) l = mid;
        else r = mid;
    }
    return l;
}

