void solve() {
    re(i, n + 1) {
        pp[i] = i;
        pps[i] = 1ll * i * i % m;
    }

    re(i, n) {
        pps[i + 1] = (pps[i + 1] + pps[i]) % m;
        pp[i + 1] = (pp[i + 1] + pp[i]) % m;
    }

    ll ans = 0;
    ll l = (k + 1) / 2;
    ll r = min(k, n);

    if (l <= r) ans = (pps[r] - pps[l - 1] + m) % m;

    l = max(1ll, k - n);
    r = (k - 1) / 2;

    if (l <= r) ans = (ans - (pps[r] - pps[l - 1] + m) % m + m) % m;

