int R, C, F;

enum MOVE { RT, LT, DR, DL, NO };

int findb(int r, int c, MOVE prevm, char** matr) {
    static __gnu_cxx::hash_set<string> memo;
    string key = to_string(r) + ":" + to_string(c) + ":" + to_string(prevm);
    if (memo.find(key) != memo.end())
        return -1;

    if (c < 0 || c >= C)
        return -1;

    if (r == R - 1 && c == C - 1)
        return 0;

    if (matr[r][c] == '1')
        return -1;

    if (r == R - 1)
        return -1;

    int res = 1000000000;

    if (prevm != RT && c + 1 < C && matr[r][c + 1] == '0')
        res = min(res, findb(r, c + 1, RT, matr));

    if (prevm != LT && c - 1 >= 0 && matr[r][c - 1] == '0')
        res = min(res, findb(r, c - 1, LT, matr));

    if (prevm != DR && r + 1 < R && c + 1 < C && matr[r + 1][c + 1] == '0')
        res = min(res, findb(r + 1, c + 1, DR, matr));

    if (prevm != DL && r + 1 < R && c - 1 >= 0 && matr[r + 1][c - 1] == '0')
        res = min(res, findb(r + 1, c - 1, DL, matr));

    if (matr[r + 1][c] == '0')
        res = min(res, findb(r + 1, c, NO, matr));

    if (res >= 1000000000) {
        memo.insert(key);
        return -1;
    }

    return 1 + res;
}

