const int fn = 10002;
const int nmx = 310;
map<string, int> M;
int A[nmx], B[nmx], C[nmx], n, nc;
vector<int> K[nmx];

inline int fun_pt(int x) { return x & (-x); }

void update_pt(int x, int vl) {
    while (x <= max_pt) {
        POW_TREE[x] = min(POW_TREE[x], vl);
        x += fun_pt(x);
    }
}

int pref_pt(int x) {
    int mn = INT_MAX;
    while (x > 0) {
        mn = min(mn, POW_TREE[x]);
        x -= fun_pt(x);
    }
    return mn;
}

bool cmp(int a, int b) {
    return A[a] > A[b];
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        M.clear();
        for (int i = 0; i < nmx; i++) {
            K[i].clear();
        }
        cin >> n;
        nc = 0;
        for (int i = 0; i < n; i++) {
            string s;
            cin >> s >> A[i] >> B[i];
            if (M.count(s) == 0) {
                M[s] = nc++;
            }
            C[i] = M[s];
            K[C[i]].push_back(i);
        }
        int res = INT_MAX;
        for (int a = 0; a < nc; a++) {
            for (int b = 0; b < nc; b++) {
                for (int c = 0; c < nc; c++) {
                    if (a == b || b == c || a == c) {
                        continue;
                    }
                    vector<int> ord;
                    for (int i : K[a]) {
                        ord.push_back(i);
                    }
                    for (int i : K[b]) {
                        ord.push_back(i);
                    }
                    for (int i : K[c]) {
                        ord.push_back(i);
                    }
                    sort(ord.begin(), ord.end(), cmp);
                    max_pt = ord.size();
                    for (int i = 0; i <= max_pt; i++) {
                        POW_TREE[i] = INT_MAX;
                    }
                    int cur = 0;
                    for (int i : ord) {
                        int mn = pref_pt(B[i]);
                        cur = max(cur, mn + 1);
                        update_pt(B[i], cur);
                    }
                    res = min(res, cur);
                }
            }
        }
        cout << res << endl;
    }
    return 0;
}
