typedef long long ll;
const int MOD = 1000000007;
const int MAX = 1000010;

ll F[MAX], Finv[MAX], inv[MAX];
ll dp0[MAX], dp1[MAX];

ll comb(int N, int K) {
    if (N < K || K < 0) return 0;
    return F[N] * Finv[K] % MOD * Finv[N-K] % MOD;
}

void pre(void) {
    inv[1] = 1;
    for (int i = 2; i < MAX; ++i) {
        inv[i] = ((MOD - inv[MOD%i]) * (MOD/i))%MOD;
    }
    F[0] = Finv[0] = 1;
    for (int i = 1; i < MAX; ++i) {
        F[i] = (F[i-1] * i) % MOD;
        Finv[i] = (Finv[i-1] * inv[i]) % MOD;
    }
    dp0[0] = 1;
    for (int i = 0; i < MAX - 1; i++) {
        dp0[i+1] = (dp0[i] * (2 * i + 1)) % MOD;
    }
    dp1[0] = 1;
    for (int i = 0; i < MAX - 1; i++) {
        dp1[i+1] = (dp1[i] * (2 * i + 2)) % MOD;
    }
}

void main2(void) {
    int N, X;
    scanf("%d %d", &N, &X);
    ll ans = 0;
    for (int i = X; i <= N; i++) {
        int j = i - X;
        ans = (ans + comb(N, i) * dp0[i] % MOD * dp1[j] % MOD) % MOD;
    }
    printf("%lld\n", ans);
}

