    int d = 0;

    lines1.clear();
    lines2.clear();

    for(int i=0; i<L; ++i) {
      char ch;
      scanf(" %c", &ch);

      if(ch == 'F') {
        int nx = x + dx[d], ny = y + dy[d];
        if(d == 0 || d == 2) {
          lines1.push_back( PII(x, y) );
          lines1.push_back( PII(nx, ny) );
        } else {
          lines2.push_back( PII(x, y) );
          lines2.push_back( PII(nx, ny) );
        }
        x = nx, y = ny;
      } else if(ch == 'R') {
        d = (d+1) % 4;
      } else {
        d = (d+3) % 4;
      }
    }

    int min_y = INF, max_y = -INF;
    int min_x = INF, max_x = -INF;

    for(int i=0; i<(int)lines1.size(); i+=2) {
      int y1 = lines1[i].first, y2 = lines1[i+1].first;
      min_y = min(min_y, min(y1, y2));
      max_y = max(max_y, max(y1, y2));
    }

    for(int i=0; i<(int)lines2.size(); i+=2) {
      int x1 = lines2[i].second, x2 = lines2[i+1].second;
      min_x = min(min_x, min(x1, x2));
      max_x = max(max_x, max(x1, x2));
    }

    memset(visited, 0, sizeof visited);
    for(int i=0; i<(int)lines1.size(); i+=2) {
      int x = lines1[i].second, y1 = lines1[i].first, y2 = lines1[i+1].first;
      if(y1 > y2) swap(y1, y2);
      for(int y=y1; y<=y2; ++y) visited[y-min_y][x-min_x] = true;
    }

    for(int i=0; i<(int)lines2.size(); i+=2) {
      int y = lines2[i].first, x1 = lines2[i].second, x2 = lines2[i+1].second;
      if(x1 > x2) swap(x1, x2);
      for(int x=x1; x<=x2; ++x) visited[y-min_y][x-min_x] = true;
    }

    int res = 0;
    for(int i=min_y; i<=max_y; ++i)
      for(int j=min_x; j<=max_x; ++j)
        if(visited[i-min_y][j-min_x]) ++res;

    #ifdef PRINT_CASE
    printf("Case %d: ", case_no);
    #endif
    printf("Case #%d: %d\n", case_no, res);
  }

  return 0;
}
