void norm(int &a, int &b, int &c){
  if (a > b) swap(a,b);
  if (a > c) swap(a,c);
  if (b > c) swap(b,c);
}

int64& getd1(int x, int y1, int y2, int y3){
  norm(y1, y2, y3);
  return d1[x][y1][y2][y3];
}

void put(int v, int c1, int c2, int c3, int value){
  getd1(v, c1, c2, c3) = value;
}

int64 go(int v, int c1, int c2, int c3){
  int64& ans = getd1(v, c1, c2, c3);
  if (ans != -1) return ans;
  if (v == n) return ans = 0;
  ans = go(v+1, c1, c2, c3);
  for (int i = 0; i < (int)a[v].size(); i++){
    if (st[v].count(a[v][i])) continue;
    int nc1 = c1, nc2 = c2, nc3 = c3;
    if (a[v][i] < c1){
      nc3 = nc2; nc2 = nc1; nc1 = a[v][i];
    } else if (a[v][i] < c2){
      nc3 = nc2; nc2 = a[v][i];
    } else if (a[v][i] < c3) {
      nc3 = a[v][i];
    } else {
      continue;
    }
    int add = (int)(a[v][i] > 0);
    ans = max(ans, go(v+1, nc1, nc2, nc3) + add);
  }
  return ans;
}

