int component[MAX], U[MAX];

void dfs1(int v) {
    U[v] = 1;
    for(int u : G[v]) {
        if(!U[u]) {
            dfs1(u);
        }
    }
    order.pb(v);
}

void dfs2(int v, int c) {
    component[v] = c;
    for(int u : GR[v]) {
        if(!component[u]) {
            dfs2(u, c);
        }
    }
}

int main() {
    ios_base::sync_with_stdio(0);
    cin.tie(0);

    int t;
    cin >> t;
    while(t--) {
        cin >> n >> m;
        for(int i = 0; i < n; i++) {
            cin >> s[i];
        }
        cnt = 0;
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                A[i][j] = -1;
            }
        }
        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(s[i][j] == '-' || s[i][j] == '|') {
                    cnt++;
                    S.clear();
                    ok = true;
                    go(i, j, s[i][j] == '-' ? 1 : 0);
                    go(i, j, s[i][j] == '-' ? 3 : 2);
                    if(!ok) {
                        cout << "IMPOSSIBLE" << endl;
                        goto end;
                    }
                    for(auto it : S) {
                        s[it.F][it.S] = s[i][j];
                    }
                }
            }
        }

        for(int i = 0; i < 2*cnt; i++) {
            G[i].clear();
            GR[i].clear();
        }

        for(int i = 0; i < n; i++) {
            for(int j = 0; j < m; j++) {
                if(s[i][j] == '.') {
                    if(inside(i-1, j) && (A[i-1][j] == 2)) {
                        G[A[i][j]].pb(A[i-1][j]);
                        GR[A[i-1][j]].pb(A[i][j]);
                    }
                    if(inside(i, j-1) && (A[i][j-1] == 3 || A[i][j-1] == 1)) {
                        G[A[i][j]].pb(A[i][j-1]);
                        GR[A[i][j-1]].pb(A[i][j]);
                    }
                    if(inside(i, j+1) && A[i][j+1] != -1 && (A[i][j+1] == 3 || A[i][j+1] == 1)) {
                        G[A[i][j+1]].pb(A[i][j]);
                        GR[A[i][j]].pb(A[i][j+1]);
                    }
                    if(inside(i+1, j) && A[i+1][j] != -1 && (A[i+1][j] == 0)) {
                        G[A[i+1][j]].pb(A[i][j]);
                        GR[A[i][j]].pb(A[i+1][j]);
                    }
                }
            }
        }

        memset(U, 0, sizeof U);
        memset(component, 0, sizeof component);
        order.clear();

        for(int i = 0; i < 2*cnt; i++) {
            if(!U[i]) {
                dfs1(i);
            }
        }

        int c = 0;
        for(int i = 2*cnt-1; i >= 0; i--) {
            int v = order[i];
            if(!component[v]) {
                c++;
                dfs2(v, c);
            }
        }

        ok = true;
        for(int i = 0; i < cnt; i++) {
            if(component[2*i] == component[2*i+1]) {
                ok = false;
                break;
            }
        }

        if(ok) {
            cout << "POSSIBLE" << endl;
            for(int i = 0; i < n; i++) {
                cout << s[i] << endl;
            }
        } else {
            cout << "IMPOSSIBLE" << endl;
        }

        end:;
    }

    return 0;
}
