int main() {
    int t;
    cin >> t;
    for (int cas = 1; cas <= t; cas++) {
        int n;
        cin >> n;
        vector<double> x(n), y(n), z(n);
        for (int i = 0; i < n; i++) {
            cin >> x[i] >> y[i] >> z[i];
        }
        bool ok = true;
        for (int i = 0; i < n; i++) {
            double bx = -y[i], by = x[i], bz = 0;
            double tx = -y[i] * z[i], ty = x[i] * z[i], tz = x[i] * x[i] + y[i] * y[i];
            double bmag = sqrt(bx * bx + by * by + bz * bz);
            double tmag = sqrt(tx * tx + ty * ty + tz * tz);
            bx /= bmag; by /= bmag; bz /= bmag;
            tx /= tmag; ty /= tmag; tz /= tmag;
            assert(abs(bx * x[i] + by * y[i] + bz * z[i]) < eps);
            assert(abs(tx * x[i] + ty * y[i] + tz * z[i]) < eps);
            assert(abs(bx * tx + by * ty + bz * tz) < eps);
            vector<double> angle;
            for (int j = 0; j < n; j++) {
                if (i == j) continue;
                if (abs(x[i] + x[j]) < eps && abs(y[i] + y[j]) < eps && abs(z[i] + z[j]) < eps) continue;
                double dot = bx * x[j] + by * y[j] + bz * z[j];
                double cross = tx * x[j] + ty * y[j] + tz * z[j];
                angle.push_back(atan2(cross, dot));
            }
            sort(angle.begin(), angle.end());
            for (int j = 0; j + 1 < angle.size(); j++) {
                if (angle[j + 1] - angle[j] > pi + eps) ok = false;
            }
            if (angle.back() - angle[0] > pi + eps) ok = false;
        }
        cout << "Case #" << cas << ": " << (ok ? "YES" : "NO") << endl;
    }
    return 0;
}
