#include <bits/stdc++.h>

using namespace std;

const int DX[] = {-1, 1, 0, 0};
const int DY[] = {0, 0, -1, 1};
const int N = 1005;

char f[N][N];
int qu[N * N][2];
int dT[N][N], d[N][N];
int usedT[N][N], used[N][N];
int timerT, timer;
bool never[N][N];

inline bool flag(int x, int y) { return f[x][y] == '#'; }
inline bool bad(int x, int y) { return x < 0 || x >= N - 1 || y < 0 || y >= N - 1; }

int bfsT(int sx, int sy, int tx, int ty, bool bf, int cx, int cy) {
    if (bad(sx, sy) || bad(tx, ty)) return 1e9;
    ++timerT;
    qu[0][0] = tx, qu[0][1] = ty;
    int x, y;
    int fr = 0, bk = 1;
    dT[tx][ty] = 0;
    usedT[tx][ty] = timerT;
    while (fr < bk) {
        x = qu[fr][0], y = qu[fr][1]; fr++;
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k], ny = y + DY[k];
            if (bad(nx, ny) || usedT[nx][ny] == timerT || (!never[nx][ny] && flag(nx, ny)))
                continue;
            if (!bf && (nx == cx && ny == cy)) continue;
            dT[nx][ny] = dT[x][y] + 1;
            qu[bk][0] = nx, qu[bk][1] = ny; bk++;
            usedT[nx][ny] = timerT;
        }
    }
    return dT[sx][sy];
}

int bfs(int sx, int sy, int tx, int ty, bool bf, int cx, int cy) {
    if (bad(sx, sy) || bad(tx, ty)) return 1e9;
    ++timer;
    qu[0][0] = sx, qu[0][1] = sy;
    int x, y;
    int fr = 0, bk = 1;
    d[sx][sy] = 0;
    used[sx][sy] = timer;
    while (fr < bk) {
        x = qu[fr][0], y = qu[fr][1]; fr++;
        for (int k = 0; k < 4; k++) {
            int nx = x + DX[k], ny = y + DY[k];
            if (bad(nx, ny) || used[nx][ny] == timer || (!never[nx][ny] && flag(nx, ny)))
                continue;
            if (!bf && (nx == cx && ny == cy)) continue;
            d[nx][ny] = d[x][y] + 1;
            qu[bk][0] = nx, qu[bk][1] = ny; bk++;
            used[nx][ny] = timer;
        }
    }
    return d[tx][ty];
}

void solve() {
    #ifdef LOCAL
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    #endif
    memset(f, 0, sizeof(f));
    int n, m;
    scanf("%d %d", &n, &m);
    for (int i = 0; i < n; i++)
        scanf("%s", f[i]);
    int sx, sy, tx, ty;
    scanf("%d %d %d %d", &sx, &sy, &tx, &ty); sx--, sy--, tx--, ty--;
    int minx = min(sx, tx), maxx = max(sx, tx);
    int miny = min(sy, ty), maxy = max(sy, ty);
    for (int x = minx; x <= maxx; x++)
        for (int y = miny; y <= maxy; y++)
            never[x][y] = true;
    int need = abs(sx - tx) + abs(sy - ty);
    int cnt = 0;
    while (bfs(sx, sy, tx, ty, cnt == 0, -1, -1) + 1 > m) {
        if (cnt == m * 2) {
            printf("IMPOSSIBLE\n");
            return;
        }
        int cx = -1, cy = -1;
        int cans = 1e9;
        bfs(sx, sy, tx, ty, true, 0, 0);
        for (int x = 0; x < n; x++)
            for (int y = 0; y < n; y++)
                if (flag(x, y) && !never[x][y] && !bad(x, y) && !bad(x + 1, y + 1) &&
                    bfsT(sx, sy, x, y, true, 0, 0) + bfsT(x + 1, y + 1, tx, ty, true, 0, 0) == need) {
                    int curans = max(d[x][y], bfsT(x + 1, y + 1, tx, ty, false, x, y));
                    if (curans < cans) {
                        cans = curans;
                        cx = x, cy = y;
                    }
                }
        assert(cx != -1);
        f[cx][cy] = f[cx + 1][cy] = f[cx][cy + 1] = f[cx + 1][cy + 1] = '.';
        never[cx][cy] = never[cx + 1][cy] = never[cx][cy + 1] = never[cx + 1][cy + 1] = true;
        cnt++;
    }
    if (bfs(sx, sy, tx, ty, false, -1, -1) != need) {
        printf("IMPOSSIBLE\n");
        return;
    }
    printf("POSSIBLE\n");
    for (int i = 0; i < n; i++)
        printf("%s\n", f[i]);
}

