int gaub(vector<vector<long double>> a) {
    int n = a.size();
    for (int i = 0; i < n; ++i) {
        int k = i;
        for (int j = i + 1; j < n; ++j)
            if (abs(a[j][i]) > abs(a[k][i]))
                k = j;
        swap(a[i], a[k]);
        if (abs(a[i][i]) < 1e-9)
            return 0;
        for (int j = i + 1; j < n; ++j) {
            long double c = a[j][i] / a[i][i];
            for (int k = i; k < n; ++k)
                a[j][k] -= a[i][k] * c;
        }
    }
    long double ans = 1;
    for (int i = 0; i < n; ++i)
        ans *= a[i][i];
    return abs(round(ans));
}

