        in >> cells >> rows >> cols;
        std::pair<int, int> tempPartialData = std::make_pair(rows, cols);
        std::pair<int, std::pair<int, int>> tempData = std::make_pair(cells, tempPartialData);
        testData.push(tempData);
    }
