}

void solveAndWrite(std::fstream& out, int numTests, std::queue<std::pair<int, std::pair<int, int>>>& testData) {
    for (int i = 1; i <= numTests; ++i) {
        int cells = testData.front().first;
        int rows = testData.front().second.first;
        int cols = testData.front().second.second;
        testData.pop();

        out << "Case #" << i << ": ";

        if (rows * cols % cells != 0 || cells >= 7 || cells > rows || cells > cols || (cells + 1) / 2 > std::min(rows, cols)) {
            out << "RICHARD\n";
        } else if (cells == 1 || cells == 2 || cells == 3) {
            out << "GABRIEL\n";
        } else if (cells == 4) {
            if (std::min(rows, cols) > 2) {
                out << "GABRIEL\n";
            } else {
                out << "RICHARD\n";
            }
        } else if (cells == 5) {
            if (std::min(rows, cols) == 3 && std::max(rows, cols) == 5) {
                out << "RICHARD\n";
            } else if (std::min(rows, cols) >= 4) {
                out << "GABRIEL\n";
            } else {
                out << "RICHARD\n";
            }
        } else if (cells == 6) {
            if (std::min(rows, cols) > 3) {
                out << "GABRIEL\n";
            } else {
                out << "RICHARD\n";
            }
        }
    }
    out.close();
}

