void solve() {
    cin >> n;
    rep(i, 1, n + 1) cin >> x[i] >> y[i] >> z[i];
    int g = gcd(gcd(abs(x[1]), abs(y[1])), abs(z[1]));
    x[1] /= g, y[1] /= g, z[1] /= g;
    rep(i, 2, n + 1) {
        int g = gcd(gcd(abs(x[i]), abs(y[i])), abs(z[i]));
        x[i] /= g, y[i] /= g, z[i] /= g;
    }
    int ok = 1;
    rep(i, 1, n + 1) {
        int has = 0;
        rep(j, 1, n + 1) if (scal(x[i], y[i], z[i], x[j], y[j], z[j]) == 0 && scal(x[i], y[i], z[i], x[j], y[j], z[j]) < 0) has = 1;
        if (!has) {
            ok = 0;
            break;
        }
        vec(pii) w;
        rep(j, 1, n + 1) if (i != j) w.pb(mp(scal(x[i], y[i], z[i], y[j] * z[i] - y[i] * z[j], z[j] * x[i] - z[i] * x[j], x[j] * y[i] - x[i] * y[j]), j));
        sort(all(w), ls);
        w.resize(unique(all(w)) - w.begin());
        vec(int) up, down;
        rep(i, 0, w.size()) {
            int u = 0;
            rep(j, 0, up.size()) if (scal(x[up[j]], y[up[j]], z[up[j]], x[w[i].ss], y[w[i].ss], z[w[i].ss]) > 0) u = 1;
            rep(j, 0, down.size()) if (scal(x[down[j]], y[down[j]], z[down[j]], x[w[i].ss], y[w[i].ss], z[w[i].ss]) < 0) u = 1;
            if (u) up.pb(w[i].ss);
            else down.pb(w[i].ss);
        }
        if (down.size() == 0 || up.size() == 0) {
            ok = 0;
            break;
        }
        rep(i, 0, up.size()) rep(j, i + 1, up.size()) if (scal(x[up[i]], y[up[i]], z[up[i]], x[up[j]], y[up[j]], z[up[j]]) < 0) {
