        if (!ok) break;
        rep(i, 0, down.size()) rep(j, i + 1, down.size()) if (scal(x[down[i]], y[down[i]], z[down[i]], x[down[j]], y[down[j]], z[down[j]]) < 0) {
            ok = 0;
            break;
        }
        if (!ok) break;
    }
    cout << (ok ? "YES" : "NO") << '\n';
