        std::cin >> n >> k >> u;

        std::vector<double> probs(n);
        double total_sum = 0.0;
        double total_product = 1.0;
        for (int i = 0; i < n; ++i) {
            std::cin >> probs[i];
            total_sum += probs[i];
            total_product *= probs[i];
        }

        std::sort(probs.rbegin(), probs.rend());

        double sum = 0.0;
        double best = total_product;
        for (int i = 0; i <= n; ++i) {
            if (i > 0) {
                sum += probs[i - 1];
            }
            double to_add = i - sum;
            if (to_add > u + eps) {
                continue;
            }
            double left = u - to_add;
            if (i < n) {
                double left_each = left / (n - i);
                if (probs[i] > left_each + eps) {
                    continue;
                }
                double result = std::pow(left_each, n - i);
                best = std::max(best, result);
            } else {
                best = 1.0;
            }
        }

        std::cout << "Case #" << test << ": " << std::fixed << std::setprecision(20) << best << std::endl;
