        res[i] = 0;
        for (int j = 0; j < k; j++) {
            if (i & (1 << j)) {
                res[i] += start[j];
            }
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < (1 << k); j++) {
            if (res[j] >= t[i]) {
                for (int l = 0; l < d[i]; l++) {
                    res[j ^ (1 << e[i][l])] = max(res[j ^ (1 << e[i][l])], res[j] + 1);
                }
            }
        }
    }
    int ans = 0;
    for (int i = 0; i < (1 << k); i++) {
        ans = max(ans, res[i]);
    }
    if (ans == 0) {
        printf("IMPOSSIBLE\n");
    } else {
        printf("%d\n", ans);
    }
}

