const int MAXN = 21;
int rows, cols;
int memo[MAXN][MAXN][MAXN][MAXN];

bool isok(int r, int c, int happy) {
    return r >= 0 && r < rows && c >= 0 && c < cols && (happy & (1 << (r * cols + c))) == 0;
}

bool proc(bool alice, int r, int c, int happy) {
    if (alice) {
        for (int i = r + 1; i < rows; i++) {
            if (isok(i, c, happy)) {
                if (!proc(!alice, i, c, happy | (1 << (i * cols + c)))) {
                    return true;
                }
            } else {
                break;
            }
        }
        for (int i = r - 1; i >= 0; i--) {
            if (isok(i, c, happy)) {
                if (!proc(!alice, i, c, happy | (1 << (i * cols + c)))) {
                    return true;
                }
            } else {
                break;
            }
        }
    } else {
        for (int j = c + 1; j < cols; j++) {
            if (isok(r, j, happy)) {
                if (!proc(!alice, r, j, happy | (1 << (r * cols + j)))) {
                    return true;
                }
            } else {
                break;
            }
        }
        for (int j = c - 1; j >= 0; j--) {
            if (isok(r, j, happy)) {
                if (!proc(!alice, r, j, happy | (1 << (r * cols + j)))) {
                    return true;
                }
            } else {
                break;
            }
        }
    }
    return false;
}

bool canWin(bool alice, int kr, int kc, int happy) {
    if (memo[kr][kc][kr][kc] != -1) {
        return memo[kr][kc][kr][kc];
    }
    bool res = proc(alice, kr, kc, happy);
    memo[kr][kc][kr][kc] = res;
    return res;
}

