    if (vis[u]) return false;
    vis[u] = true;
    for (int v = 0; v < 3000; v++)
        if (cn[u][v] && dfs(v, snk)) {
            cn[u][v] = false;
            cn[v][u] = true;
            return true;
        }
    return false;
}

int dfs2(int u, int v, vector<int>& asn, vector<int>& rasn) {
    if (u == v) return 2;
    if (vis[u]) return 0;
    vis[u] = true;
    for (int v2 : cndeps[u][v])
        if (dfs2(rasn[v2], v2, asn, rasn) == 2) {
            asn[u] = v;
            rasn[v] = u;
            return 1;
        }
    return 0;
}

