inline LL points(LL d) {
    return d * (d - 1) / 2 % MOD;
}

int solve() {
    int n, m;
    scanf("%d%d", &n, &m);
    LL res = 0;
    REP(i, m) {
        LL a, b;
        scanf("%lld%lld", &a, &b);
        res = (res + points(b + 1) - points(a) + MOD) % MOD;
    }
    priority_queue<TRI> q;
    REP(i, m) {
        LL a, b;
        scanf("%lld%lld", &a, &b);
        q.push(TRI(b, PI(a, i)));
    }
    VI last(m, -1);
    while(!q.empty()) {
        int i = q.top().second.second;
        LL a = q.top().second.first;
        LL b = q.top().first;
        q.pop();
        LL dec = (i == 0) ? points(n + 1) - points(b) : points(b - last[i - 1]) - points(a - last[i - 1]);
        res = (res - dec % MOD + MOD) % MOD;
        last[i] = b;
    }
    return res;
}

