long long pp[1005][1005];
int MOD = 1000002013;

int main(int argc, char **argv) {
    int T;
    scanf("%d", &T);
    FOR(cas, 1, T) {
        oindex.clear(); eindex.clear();
        memset(oo, 0, sizeof(oo)); memset(ee, 0, sizeof(ee));
        oocnt = eecnt = 0;
        memset(pp, 0, sizeof(pp));

        int N, M;
        scanf("%d %d", &N, &M);
        REP(i, M) {
            int o, e, p;
            scanf("%d %d %d", &o, &e, &p);
            if (oindex.count(o) == 0) {
                oindex[o] = oocnt++;
                oo[oindex[o]] = o;
            }
            if (eindex.count(e) == 0) {
                eindex[e] = eecnt++;
                ee[eindex[e]] = e;
            }
            pp[oindex[o]][eindex[e]] += p;
        }

        REP(i, oocnt) {
            FOR(j, 1, eecnt - 1) {
                pp[i][j] += pp[i][j - 1];
            }
        }

        long long res = 0;
        REP(i, eecnt) {
            long long tmp = 0;
            REP(j, oocnt) {
                tmp += pp[j][i];
                tmp %= MOD;
                res += tmp * (oo[j] ^ ee[i]);
                res %= MOD;
            }
        }

        printf("Case #%d: %lld\n", cas, res);
    }
    return 0;
}
#include <cstdio>
