using namespace std;

const double eps = 1e-8;
const int maxn = 10010;

struct Point {
    double x, y;
} u[maxn], l[maxn];

int L, U;
vector<double> ans;

double getuy(double x) {
    int i;
    for (i = 0; i < U; i++)
        if (u[i].x > x) break;
    if (i == 0) return u[0].y;
    if (i == U) return u[U - 1].y;
    return u[i - 1].y + (u[i].y - u[i - 1].y) * (x - u[i - 1].x) / (u[i].x - u[i - 1].x);
}

double getly(double x) {
    int i;
    for (i = 0; i < L; i++)
        if (l[i].x > x) break;
    if (i == 0) return l[0].y;
    if (i == L) return l[L - 1].y;
    return l[i - 1].y + (l[i].y - l[i - 1].y) * (x - l[i - 1].x) / (l[i].x - l[i - 1].x);
}

int main() {
    freopen("input.txt", "r", stdin);
    freopen("output.txt", "w", stdout);
    int T;
    scanf("%d", &T);
    for (int cas = 1; cas <= T; cas++) {
        double W, G, S = 0;
        scanf("%lf%d%d%lf", &W, &L, &U, &G);
        for (int i = 0; i < L; i++) {
            scanf("%lf%lf", &l[i].x, &l[i].y);
            if (i > 0) S += (l[i].y + l[i - 1].y) * (l[i].x - l[i - 1].x) / 2;
        }
        for (int i = 0; i < U; i++) {
            scanf("%lf%lf", &u[i].x, &u[i].y);
            if (i > 0) S -= (u[i].y + u[i - 1].y) * (u[i].x - u[i - 1].x) / 2;
        }
        S /= W;
        ans.clear();
        ans.push_back(0);
        for (int i = 1; i < G; i++) {
            double L = ans[i - 1], R = W;
            while (R - L > eps) {
                double mid = (L + R) / 2;
                double s = 0;
                for (int j = 0; j < i; j++) {
                    double l = ans[j], r = (j == i - 1) ? mid : ans[j + 1];
                    s += (getuy(l) + getuy(r)) * (r - l) / 2;
                    s -= (getly(l) + getly(r)) * (r - l) / 2;
                }
                if (s < S * i) L = mid;
                else R = mid;
            }
            ans.push_back(L);
        }
        ans.push_back(W);
        printf("Case #%d:", cas);
        for (int i = 0; i <= G; i++)
            printf(" %.10f", ans[i]);
        printf("\n");
    }
    return 0;
}
