unsigned int calc(int l, int p) {
    if (a[l][p] != -1) return a[l][p];
    if (l * C >= p) return a[l][p] = 0;
    unsigned int b = -1;
    for (int x = l + 1; x < p; x++)
        b = min(b, 1 + max(calc(l, x), calc(x, p)));
    assert(b != -1);
    return a[l][p] = b;
}

