typedef pair<int, int> pii;

const int E = 100010, V = 1010;

int e[E], nxt[E], cap[E], st[V], cur[V], h[V];
int ST, FN, n, m, ecnt;

void add_edge(int p, int q, int f1, int f2) {
    e[ecnt] = q, nxt[ecnt] = st[p], cap[ecnt] = f1, st[p] = ecnt++;
    e[ecnt] = p, nxt[ecnt] = st[q], cap[ecnt] = f2, st[q] = ecnt++;
}

int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

char block[310][310];

bool ok(int i, int j) {
    return i >= 0 && i < n && j >= 0 && j < m && block[i][j] == '.';
}

bool bfs() {
    memset(h, -1, sizeof h);
    queue<int> q;
    q.push(ST), h[ST] = 0;
    while (!q.empty()) {
        int k = q.front();
        q.pop();
        rep(i, st[k], st[k + 1] - 1) {
            int p = e[i];
            if (cap[i] > 0 && h[p] == -1) {
                h[p] = h[k] + 1;
                if (p == FN)
                    return true;
                q.push(p);
            }
        }
    }
    return false;
}

int dfs(int k, int low) {
    if (k == FN)
        return low;
    int s = 0;
    for (int &i = cur[k]; i < st[k + 1]; i++) {
        int p = e[i];
        if (cap[i] > 0 && h[p] == h[k] + 1) {
            int t = dfs(p, min(low - s, cap[i]));
            cap[i] -= t;
            cap[i ^ 1] += t;
            s += t;
            if (s == low)
                break;
        }
    }
    return s;
}

