        ST = 0, FN = n * m + 1;
        rep(i, 1, FN) st[i] = ecnt;
        rep(i, 0, n - 1) rep(j, 0, m - 1) {
            int k = i * m + j + 1;
            if (i == 0)
                add_edge(ST, k, 1, 0);
            else if (i == n - 1)
                add_edge(k, FN, 1, 0);
            if (block[i][j] == 'x')
                continue;
            rep(t, 0, 3) {
                int ni = i + dx[t], nj = j + dy[t];
                if (!ok(ni, nj))
                    continue;
                int p = ni * m + nj + 1;
                add_edge(k, p, 1, 0);
            }
        }
        int ans = 0;
        while (bfs()) {
            memcpy(cur, st, sizeof st);
            ans += dfs(ST, 0x3f3f3f3f);
        }
        printf("Case #%d: %d\n", ca, ans);
    }
    return 0;
}
