void inicializa() {
    for (int i = 2; i <= 10; i++) {
        pot[i][0] = 1;
        for (int j = 1; j <= 20; j++) {
            pot[i][j] = pot[i][j - 1] * i;
        }
    }
}

bool happy(int k, int b) {
    int history[500], count = 0;
    while (1) {
        convierte(k, b);
        int sum = 0;
        for (int j = number[0]; j > 0; j--) {
            sum += number[j] * number[j];
        }
        if (sum == 1)
            return true;
        int i;
        for (i = 1; i <= count; i++)
            if (sum == history[i])
                break;
        if (i <= count)
            return false;
        history[++count] = sum;
        k = sum;
    }
}

void convierte(int n, int b) {
    int i = 0;
    while (n > 0) {
        number[++i] = n % b;
        n /= b;
    }
    number[0] = i;
}

int main() {
    int T;
    cin >> T;
    inicializa();
    for (int caso = 1; caso <= T; caso++) {
        cin >> string;
        bases = 0;
