using namespace std;

const int MAXN = 10;

int n, m;
bool A[MAXN][MAXN], B[MAXN][MAXN];
int f[MAXN];
bool used[MAXN];

void init() {
    memset(A, 0, sizeof(A));
    memset(B, 0, sizeof(B));
    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        A[a][b] = A[b][a] = 1;
    }
    scanf("%d", &m);
    for (int i = 1; i < m; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        B[a][b] = B[b][a] = 1;
    }
}

int makeSearch(int p) {
    if (p == m) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (A[i][j] != B[f[i]][f[j]]) {
                    return 0;
                }
            }
        }
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            f[p] = i;
            used[i] = true;
            if (makeSearch(p + 1)) {
                return 1;
            }
            used[i] = false;
        }
    }
    return 0;
}

void solve() {
    memset(used, 0, sizeof(used));
    if (makeSearch(0)) {
        printf("YES\n");
    } else {
        printf("NO\n");
    }
}

