bool mygreater(const string& a, const string& b) {
    if (a.size() != b.size())
        return a.size() > b.size();
    return a > b;
}

int main() {
    int T;
    cin >> T;
    while (T--) {
        int W, Q;
        cin >> W >> Q;
        M.resize(W);
        for (int i = 0; i < W; i++)
