        for (int i = 0; i < Q; i++)
            cin >> q[i];
        memset(curr, 0, sizeof(curr));
        for (int i = 0; i < W; i++) {
            for (int j = 0; j < W; j++) {
                curr[i][j][M[i][j] - '0'] = M[i][j];
            }
        }
        while (true) {
            for (int i = 0; i < Q; i++) {
                for (int r = 0; r < W; r++) {
                    for (int c = 0; c < W; c++) {
                        if (curr[r][c][q[i]].size() > 0) {
                            if (mygreater(curr[r][c][q[i]], queries[i]))
                                queries[i] = curr[r][c][q[i]];
                        }
                    }
                }
            }
            bool done = true;
            for (int i = 0; i < Q; i++) {
                if (queries[i].empty()) {
                    done = false;
                    break;
                }
            }
            if (done)
                break;
            memset(next, 0, sizeof(next));
            for (int i = 0; i < W; i++) {
                for (int j = 0; j < W; j++) {
                    for (int s = 0; s < MAX; s++) {
