                            string str = curr[i][j][s];
                            if (i > 0) {
                                int ns = s + (M[i - 1][j] == '+' ? 1 : -1) * (M[i - 1][j] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i - 1][j], next[i - 1][j][ns]))
                                    next[i - 1][j][ns] = str + M[i - 1][j];
                            }
                            if (i < W - 1) {
                                int ns = s + (M[i + 1][j] == '+' ? 1 : -1) * (M[i + 1][j] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i + 1][j], next[i + 1][j][ns]))
                                    next[i + 1][j][ns] = str + M[i + 1][j];
                            }
                            if (j > 0) {
                                int ns = s + (M[i][j - 1] == '+' ? 1 : -1) * (M[i][j - 1] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i][j - 1], next[i][j - 1][ns]))
                                    next[i][j - 1][ns] = str + M[i][j - 1];
                            }
                            if (j < W - 1) {
                                int ns = s + (M[i][j + 1] == '+' ? 1 : -1) * (M[i][j + 1] - '0');
                                if (ns >= 0 && ns < MAX && mygreater(str + M[i][j + 1], next[i][j + 1][ns]))
                                    next[i][j + 1][ns] = str + M[i][j + 1];
                            }
                        }
                    }
                }
            }
            swap(curr, next);
        }
        for (int i = 0; i < Q; i++)
            cout << queries[i] << endl;
        cout << endl;
    }
    return 0;
}
