int main() {
    cin >> t;
    for (int l = 0; l < t; l++) {
        int n, a, b, c, d, x0, y0, m;
        cin >> n >> a >> b >> c >> d >> x0 >> y0 >> m;

        int x[n], y[n];
        x[0] = x0;
        y[0] = y0;

        for (int i = 1; i < n; i++) {
            x[i] = (a * x[i-1] + b) % m;
            y[i] = (c * y[i-1] + d) % m;
        }

        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                for (int k = j+1; k < n; k++) {
                    if (x[i] == x[j] && y[i] == y[j]) continue;
                    if (x[i] == x[k] && y[i] == y[k]) continue;
                    if (x[j] == x[k] && y[j] == y[k]) continue;
                    if ((x[i] + x[j] + x[k]) % 3 == 0 && (y[i] + y[j] + y[k]) % 3 == 0) ans++;
                }
            }
        }

        cout << "Case #" << l+1 << ": " << ans << endl;
    }

    return 0;
}
#include <bits/stdc++.h>
using namespace std;

const int MAX = 110;

long long n, M, t, A, B, C, D, x0, y0, ans;
long long pnt[MAX][2];

int main() {
    freopen("in.txt", "r", stdin);
    freopen("out.txt", "w", stdout);

    cin >> t;
    for (int tc = 1; tc <= t; tc++) {
        cin >> n >> A >> B >> C >> D >> x0 >> y0 >> M;

        pnt[0][0] = x0;
        pnt[0][1] = y0;
        ans = 0;

        for (int i = 1; i < n; i++) {
            x0 = (A * x0 + B) % M;
            y0 = (C * y0 + D) % M;
            pnt[i][0] = x0;
            pnt[i][1] = y0;
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int k = j + 1; k < n; k++) {
                    long long sumx = pnt[i][0] + pnt[j][0] + pnt[k][0];
                    long long sumy = pnt[i][1] + pnt[j][1] + pnt[k][1];
                    if (sumx % 3 == 0 && sumy % 3 == 0) {
                        ans++;
                    }
                }
            }
        }

        cout << "Case " << tc << ": " << ans << '\n';
    }

    return 0;
}
